            i = exp.rfind('{', 0, j - 1)
            a, c = exp[:i], exp[j + 1 :]
            for b in exp[i + 1 : j].split(','):
                dfs(a + b + c)

        s = set()
        dfs(expression)
        return sorted(s)

class Solution:
    def breakPalindrome(self, palindrome: str) -> str:
        n = len(palindrome)
        if n == 1:
            return ""
        s = list(palindrome)
        i = 0
        while i < n // 2 and s[i] == "a":
            i += 1
        if i == n // 2:
            s[-1] = "b"
        else:
            s[i] = "a"
        return "".join(s)

class Solution:
    def leastBricks(self, wall: List[List[int]]) -> int:
        cnt = Counter()
        for row in wall:
            s = 0
            for x in row[:-1]:
                s += x
                cnt[s] += 1
        return len(wall) - max(cnt.values(), default=0)

class Solution:
    def hitBricks(self, grid: List[List[int]], hits: List[List[int]]) -> List[int]:
        m = len(grid)
        if m == 0:
            return []
        n = len(grid[0])
        n_cols = n
        virtual = m * n
        grid_copy = [row[:] for row in grid]
        is_brick = [False] * len(hits)

        for i in range(len(hits)):
            x, y = hits[i]
            if grid[x][y] == 1:
                is_brick[i] = True
                grid_copy[x][y] = 0  # Mark the hit as removed initially

        # DSU class definition
        class DSU:
            def __init__(self, size):
                self.parent = list(range(size + 1))
                self.size = [1] * (size + 1)

            def find(self, x):
                if self.parent[x] != x:
                    self.parent[x] = self.find(self.parent[x])
                return self.parent[x]

            def union(self, x, y):
                x_root = self.find(x)
                y_root = self.find(y)
                if x_root == y_root:
                    return
                if self.size[x_root] < self.size[y_root]:
                    x_root, y_root = y_root, x_root
                self.parent[y_root] = x_root
                self.size[x_root] += self.size[y_root]

        dsu = DSU(m * n)

        # Initialize the DSU based on the modified grid (grid_copy)
        for i in range(m):
            for j in range(n):
                if grid_copy[i][j] == 1:
                    current = i * n_cols + j
                    if i == 0:
                        dsu.union(current, virtual)
                    # Check left
                    if j > 0 and grid_copy[i][j - 1] == 1:
                        left = current - 1
                        dsu.union(current, left)
                    # Check above
                    if i > 0 and grid_copy[i - 1][j] == 1:
                        above = (i - 1) * n_cols + j
                        dsu.union(current, above)

        res = []
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        for idx in reversed(range(len(hits))):
            hit = hits[idx]
            x, y = hit
            if not is_brick[idx]:
                res.append(0)
                continue
            cell_id = x * n_cols + y
            grid_copy[x][y] = 1  # Re-add the brick

            initial_size = dsu.size[dsu.find(virtual)]

            current = cell_id
            # Union with the virtual node if in the first row
            if x == 0:
                dsu.union(current, virtual)

            # Check all four directions
            for dx, dy in directions:
                nx = x + dx
                ny = y + dy
                if 0 <= nx < m and 0 <= ny < n:
                    if grid_copy[nx][ny] == 1:
                        neighbor_id = nx * n_cols + ny
                        dsu.union(current, neighbor_id)

            final_size = dsu.size[dsu.find(virtual)]
            delta = final_size - initial_size
            cnt = delta - 1 if delta > 0 else 0
            res.append(cnt)

        # Reverse the result to match the original hits order
        return res[::-1]

class Solution:
    def brightestPosition(self, lights: List[List[int]]) -> int:
        d = defaultdict(int)
        for i, j in lights:
            l, r = i - j, i + j
            d[l] += 1
            d[r + 1] -= 1
        ans = s = mx = 0
        for k in sorted(d):
            s += d[k]
            if mx < s:
                mx = s
                ans = k
        return ans

class Solution:
    def brokenCalc(self, startValue: int, target: int) -> int:
        ans = 0
        while startValue < target:
            if target & 1:
                target += 1
            else:
                target >>= 1
            ans += 1
        ans += startValue - target
        return ans

class Solution:
    def buddyStrings(self, s: str, goal: str) -> bool:
