class Solution:
    def minDeletionSize(self, strs: List[str]) -> int:
        n = len(strs)
        if n == 0:
            return 0
        m = len(strs[0])
        sorted_pairs = [False] * (n - 1)
        deletions = 0

        for j in range(m):
            # Check if current column can be kept
            can_keep = True
            for i in range(n - 1):
                if not sorted_pairs[i]:
                    if strs[i][j] > strs[i+1][j]:
                        can_keep = False
                        break
            if not can_keep:
                deletions += 1
                continue

            # Update sorted_pairs for those not yet sorted
            for i in range(n - 1):
                if not sorted_pairs[i]:
                    if strs[i][j] < strs[i+1][j]:
                        sorted_pairs[i] = True

            # Early exit if all pairs are sorted
            if all(sorted_pairs):
                break

        return deletions

