class Solution:
    def boxDelivering(
        self, boxes: List[List[int]], portsCount: int, maxBoxes: int, maxWeight: int
    ) -> int:
        n = len(boxes)
        ws = list(accumulate((box[1] for box in boxes), initial=0))
        c = [int(a != b) for a, b in pairwise(box[0] for box in boxes)]
        cs = list(accumulate(c, initial=0))
        f = [0] * (n + 1)
        q = deque([0])
        for i in range(1, n + 1):
            while q and (i - q[0] > maxBoxes or ws[i] - ws[q[0]] > maxWeight):
                q.popleft()
            if q:
                f[i] = cs[i - 1] + f[q[0]] - cs[q[0]] + 2
            if i < n:
                while q and f[q[-1]] - cs[q[-1]] >= f[i] - cs[i]:
                    q.pop()
                q.append(i)
        return f[n]

import bisect

class Solution:
    def maxDepthBST(self, order: List[int]) -> int:
        if not order:
            return 0

        sorted_list = []
        depth = {}
        max_depth = 0

        for x in order:
            idx = bisect.bisect_left(sorted_list, x)
            predecessor = sorted_list[idx-1] if idx > 0 else None
            successor = sorted_list[idx] if idx < len(sorted_list) else None

            current_depth = 1
            if predecessor is not None:
                current_depth = max(current_depth, depth[predecessor] + 1)
            if successor is not None:
                current_depth = max(current_depth, depth[successor] + 1)

            depth[x] = current_depth
            if current_depth > max_depth:
                max_depth = current_depth

            bisect.insort(sorted_list, x)

        return max_depth

