class Solution:
    def getWordsInLongestSubsequence(self, words: List[str], groups: List[int]) -> List[str]:
        n = len(words)
        if n == 0:
            return []
        lengths = [len(word) for word in words]
        dp = [(1, -1) for _ in range(n)]
        max_len = 1
        best_idx = 0

        for i in range(n):
            for j in range(i):
                if groups[i] != groups[j] and lengths[i] == lengths[j]:
                    s = words[j]
                    t = words[i]
                    diff = 0
                    for a, b in zip(s, t):
                        if a != b:
                            diff += 1
                            if diff > 1:
                                break
                    if diff == 1:
                        if dp[j][0] + 1 > dp[i][0]:
                            dp[i] = (dp[j][0] + 1, j)
            if dp[i][0] > max_len:
                max_len = dp[i][0]
                best_idx = i

        path = []
        current = best_idx
        while current != -1:
            path.append(current)
            current = dp[current][1]
        path = path[::-1]
        return [words[i] for i in path]

class Solution:
    def longestValidParentheses(self, s: str) -> int:
        n = len(s)
        f = [0] * (n + 1)
        for i, c in enumerate(s, 1):
            if c == ")":
                if i > 1 and s[i - 2] == "(":
                    f[i] = f[i - 2] + 2
                else:
                    j = i - f[i - 1] - 1
                    if j and s[j - 1] == "(":
                        f[i] = f[i - 1] + 2 + f[j - 1]
        return max(f)

class Solution:
