class Solution:
    def minCost(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        dirs = [[0, 0], [0, 1], [0, -1], [1, 0], [-1, 0]]
        q = deque([(0, 0, 0)])
        vis = set()
        while q:
            i, j, d = q.popleft()
            if (i, j) in vis:
                continue
            vis.add((i, j))
            if i == m - 1 and j == n - 1:
                return d
            for k in range(1, 5):
                x, y = i + dirs[k][0], j + dirs[k][1]
                if 0 <= x < m and 0 <= y < n:
                    if grid[i][j] == k:
                        q.appendleft((x, y, d))
                    else:
                        q.append((x, y, d + 1))
        return -1

from typing import List

class Solution:
    def mergeStones(self, stones: List[int], k: int) -> int:
        n = len(stones)
        if (n - 1) % (k - 1) != 0:
            return -1

        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + stones[i]

        INF = float('inf')
        # Initialize DP table: dp[i][j][m]
        dp = [[[INF] * (n + 1) for _ in range(n)] for __ in range(n)]

        for i in range(n):
            dp[i][i][1] = 0

        for l in range(2, n + 1):
            for i in range(n - l + 1):
                j = i + l - 1
                current_sum = prefix[j + 1] - prefix[i]

                for m in range(2, l + 1):
                    if (l - m) % (k - 1) != 0:
                        continue
                    min_cost = INF
                    for mid in range(i, j):
                        for m1 in range(1, m):
                            m2 = m - m1
                            left_len = mid - i + 1
                            right_len = j - mid
                            if (left_len - m1) % (k - 1) != 0 or (right_len - m2) % (k - 1) != 0:
                                continue
                            cost = dp[i][mid][m1] + dp[mid + 1][j][m2]
                            if cost < min_cost:
                                min_cost = cost
                    if min_cost != INF:
                        dp[i][j][m] = min_cost

                # Handle m=1 after other m's
                if (l - 1) % (k - 1) == 0:
                    m_needed = k
                    if m_needed <= l and dp[i][j][m_needed] != INF:
                        dp[i][j][1] = dp[i][j][m_needed] + current_sum
                else:
                    dp[i][j][1] = INF

        return dp[0][n - 1][1] if dp[0][n - 1][1] != INF else -1

class Solution:
    def minCostToMoveChips(self, position: List[int]) -> int:
        a = sum(p % 2 for p in position)
        b = len(position) - a
        return min(a, b)

class Solution:
    def minimumCost(self, n: int, highways: List[List[int]], discounts: int) -> int:
        g = defaultdict(list)
        for a, b, c in highways:
            g[a].append((b, c))
            g[b].append((a, c))
        q = [(0, 0, 0)]
        dist = [[inf] * (discounts + 1) for _ in range(n)]
        while q:
            cost, i, k = heappop(q)
            if k > discounts:
                continue
            if i == n - 1:
                return cost
            if dist[i][k] > cost:
                dist[i][k] = cost
                for j, v in g[i]:
                    heappush(q, (cost + v, j, k))
                    heappush(q, (cost + v // 2, j, k + 1))
        return -1

class Solution:
    def minCost(
        self, maxTime: int, edges: List[List[int]], passingFees: List[int]
    ) -> int:
        m, n = maxTime, len(passingFees)
        f = [[inf] * n for _ in range(m + 1)]
        f[0][0] = passingFees[0]
        for i in range(1, m + 1):
            for x, y, t in edges:
                if t <= i:
                    f[i][x] = min(f[i][x], f[i - t][y] + passingFees[x])
                    f[i][y] = min(f[i][y], f[i - t][x] + passingFees[y])
        ans = min(f[i][n - 1] for i in range(m + 1))
        return ans if ans < inf else -1

