class Solution:
    def rotateTheBox(self, boxGrid: List[List[str]]) -> List[List[str]]:
        m = len(boxGrid)
        if m == 0:
            return []
        n = len(boxGrid[0])

        # Create the rotated matrix of size n x m
        rotated = [['.' for _ in range(m)] for _ in range(n)]

        for i in range(m):
            for j in range(n):
                new_row = j
                new_col = m - 1 - i
                rotated[new_row][new_col] = boxGrid[i][j]

        # Process each column in the rotated matrix to let stones fall
        for col in range(m):
            available = n - 1  # starting from the bottom row
            for r in range(n-1, -1, -1):
                current = rotated[r][col]
                if current == '*':
                    # Obstacle encountered, stones can't pass below this
                    available = r - 1
                elif current == '#':
                    # Move the stone to the available position
                    rotated[r][col] = '.'  # current position becomes empty
                    rotated[available][col] = '#'  # place stone at available spot
                    available -= 1  # move available up

        return rotated

class Solution:
    def orangesRotting(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        cnt = 0
        q = deque()
        for i, row in enumerate(grid):
            for j, x in enumerate(row):
                if x == 2:
                    q.append((i, j))
                elif x == 1:
                    cnt += 1
        ans = 0
        dirs = (-1, 0, 1, 0, -1)
        while q and cnt:
            ans += 1
            for _ in range(len(q)):
                i, j = q.popleft()
                for a, b in pairwise(dirs):
                    x, y = i + a, j + b
                    if 0 <= x < m and 0 <= y < n and grid[x][y] == 1:
                        grid[x][y] = 2
                        q.append((x, y))
                        cnt -= 1
                        if cnt == 0:
                            return ans
        return -1 if cnt else 0

